self.onInit = function() {
    self._riegoTimewindowHandler = function(e) {
        var ts = parseInt(e.detail.ts);
        if (!ts || isNaN(ts)) return;

        var start = new Date(ts);
        start.setHours(0, 0, 0, 0);
        var end = new Date(ts);
        end.setDate(end.getDate() + 1);
        end.setHours(0, 0, 1, 0);

        // Desde el dashboard raíz esto SÍ funciona y afecta a los popups
        self.ctx.dashboard.onUpdateTimewindow(start.getTime(), end.getTime());
    };

    window.addEventListener('riego-set-timewindow', self._riegoTimewindowHandler);
};

self.onDestroy = function() {
    if (self._riegoTimewindowHandler) {
        window.removeEventListener('riego-set-timewindow', self._riegoTimewindowHandler);
        self._riegoTimewindowHandler = null;
    }
};

